require "rails_helper"

RSpec.describe "Prepared service idempotency receipts" do
  # "The same operation_id from two services, or from two companies, gives separate receipts"
  it "prepared service receipts refuse a second row with the same company, service, operation and key and accept it for another service or company" do
    connection = ActiveRecord::Base.connection
    insert = lambda do |company_id, actor_name|
      connection.execute(<<~SQL.squish)
        INSERT INTO service_idempotency_receipts (company_id, actor_name, operation, key, fingerprint, status, body, created_at)
        VALUES (#{company_id}, #{connection.quote(actor_name)}, 'commit', 'op-1', 'fp', 200, '{}', now())
      SQL
    end

    insert.call(1, "invoice-boundary")
    insert.call(1, "invoice-cleanup")
    insert.call(2, "invoice-boundary")

    expect { connection.transaction(requires_new: true) { insert.call(1, "invoice-boundary") } }
      .to raise_error(ActiveRecord::RecordNotUnique)
    expect(connection.select_value("SELECT COUNT(*) FROM service_idempotency_receipts").to_i).to eq(3)
  end
end

require "rails_helper"

RSpec.describe "Prepared service idempotency receipts" do
  # "The same operation_id from two services, or from two companies, gives separate receipts"
  it "prepared service receipts refuse a duplicate key and accept it under another service or company" do
    connection = ActiveRecord::Base.connection
    insert = lambda do |company_id, actor_name|
      connection.execute(ActiveRecord::Base.sanitize_sql_array([<<~SQL.squish, company_id, actor_name]))
        INSERT INTO service_idempotency_receipts (company_id, actor_name, operation, key, fingerprint, status, body, created_at)
        VALUES (?, ?, 'commit', 'same-key', 'f', 200, '{}', NOW())
      SQL
    end

    insert.call(1, "invoice-boundary")
    insert.call(1, "invoice-cleanup")
    insert.call(2, "invoice-boundary")

    expect { connection.transaction(requires_new: true) { insert.call(1, "invoice-boundary") } }
      .to raise_error(ActiveRecord::RecordNotUnique)
    expect(connection.columns("service_idempotency_receipts").reject(&:null).map(&:name))
      .to include("company_id", "actor_name", "operation", "key", "fingerprint", "status", "body", "created_at")
    expect(connection.columns("idempotency_records").find { |column| column.name == "actor_id" }.null).to be(false)
    expect(connection.columns("idempotency_records").map(&:name)).not_to include("actor_name")
  end
end

RSpec.describe "Prepared service idempotency receipts against Timekeeping's schema" do
  # Each column as [type, NOT NULL, precision, limit], read from Timekeeping's
  # schema file the way spec/db/timekeeping_prepared_tables_spec.rb reads it,
  # so drift between the two applications' receipt tables fails here.
  def timekeeping_service_receipt_columns
    columns = { "id" => ["integer", true, nil, 8] }
    inside = false
    File.readlines(Rails.root.join("timekeeping/db/schema.rb")).each do |line|
      if line.match?(/^\s*create_table "service_idempotency_receipts"/)
        inside = true
      elsif inside && (column = line.match(/^\s*t\.(\w+) "(\w+)"(.*)$/))
        type, options = column[1], column[3]
        precision = options[/precision: (\d+)/, 1]&.to_i || (type == "datetime" ? 6 : nil)
        limit = options[/limit: (\d+)/, 1]&.to_i || { "bigint" => 8, "integer" => 4 }[type]
        columns[column[2]] = [type == "bigint" ? "integer" : type, options.include?("null: false"), precision, limit]
      elsif inside && line.match?(/^\s*end\s*$/)
        break
      end
    end
    columns
  end

  it "gives the prepared service receipts Timekeeping's columns, a NOT NULL company_id and no rows" do
    connection = ActiveRecord::Base.connection
    live = connection.columns("service_idempotency_receipts").to_h do |column|
      [column.name, [column.type.to_s, !column.null, column.precision, column.limit]]
    end

    expect(live).to eq(timekeeping_service_receipt_columns)
    expect(live.fetch("company_id")[1]).to be(true)
    expect(connection.select_value("SELECT COUNT(*) FROM service_idempotency_receipts").to_i).to eq(0)
    expect(Timekeeping::LocalOwner::ServiceReceipt.table_name).to eq("service_idempotency_receipts")
  end
end
